"""sklearn.gaussian_process.kernels — kernel functions for GP regression."""

import numpy as _np


class Kernel:
    """Base GP kernel — defines the (lazy) covariance function."""

    def __call__(self, X, Y=None, eval_gradient=False):
        raise NotImplementedError

    def __add__(self, other):  return Sum(self, other)
    def __mul__(self, other):  return Product(self, other)
    def __pow__(self, other):  return Exponentiation(self, other)
    def diag(self, X):         return _np.diag(self(X))
    def is_stationary(self):   return True


class StationaryKernelMixin:
    """Marker that a kernel is stationary (k(x, y) = k(x - y))."""
    def is_stationary(self): return True


class NormalizedKernelMixin:
    """Kernels whose diagonal is constant 1."""
    def diag(self, X): return _np.ones(len(X))


class GenericKernelMixin:
    """Kernels that operate on arbitrary inputs (not just arrays)."""
    pass


class KernelOperator(Kernel):
    """Base class for binary kernel operators (Sum, Product)."""
    def __init__(self, k1, k2):
        self.k1 = k1; self.k2 = k2


class Sum(KernelOperator):
    def __call__(self, X, Y=None, eval_gradient=False):
        return self.k1(X, Y) + self.k2(X, Y)


class Product(KernelOperator):
    def __call__(self, X, Y=None, eval_gradient=False):
        return self.k1(X, Y) * self.k2(X, Y)


class Exponentiation(Kernel):
    def __init__(self, kernel, exponent):
        self.kernel = kernel; self.exponent = exponent
    def __call__(self, X, Y=None, eval_gradient=False):
        return self.kernel(X, Y) ** self.exponent


class Hyperparameter(object):
    """Spec for a kernel hyperparameter."""
    def __init__(self, name, value_type, bounds, n_elements=1, fixed=None):
        self.name = name; self.value_type = value_type
        self.bounds = bounds; self.n_elements = n_elements
        self.fixed = fixed


class ConstantKernel(StationaryKernelMixin, Kernel):
    def __init__(self, constant_value=1.0, constant_value_bounds=(1e-5, 1e5)):
        self.constant_value = constant_value
    def __call__(self, X, Y=None, eval_gradient=False):
        Y = X if Y is None else Y
        return _np.full((len(X), len(Y)), self.constant_value)


class WhiteKernel(StationaryKernelMixin, Kernel):
    def __init__(self, noise_level=1.0, noise_level_bounds=(1e-5, 1e5)):
        self.noise_level = noise_level
    def __call__(self, X, Y=None, eval_gradient=False):
        if Y is None:
            return _np.eye(len(X)) * self.noise_level
        return _np.zeros((len(X), len(Y)))


class RBF(StationaryKernelMixin, NormalizedKernelMixin, Kernel):
    def __init__(self, length_scale=1.0, length_scale_bounds=(1e-5, 1e5)):
        self.length_scale = length_scale
    def __call__(self, X, Y=None, eval_gradient=False):
        from sklearn.metrics.pairwise import euclidean_distances
        Y = X if Y is None else Y
        d2 = euclidean_distances(X, Y, squared=True)
        return _np.exp(-0.5 * d2 / self.length_scale ** 2)


class Matern(RBF):
    def __init__(self, length_scale=1.0, length_scale_bounds=(1e-5, 1e5), nu=1.5):
        super().__init__(length_scale, length_scale_bounds)
        self.nu = nu
    def __call__(self, X, Y=None, eval_gradient=False):
        from sklearn.metrics.pairwise import euclidean_distances
        Y = X if Y is None else Y
        d = euclidean_distances(X, Y) / self.length_scale
        if self.nu == 0.5:
            return _np.exp(-d)
        if self.nu == 1.5:
            t = _np.sqrt(3) * d
            return (1 + t) * _np.exp(-t)
        if self.nu == 2.5:
            t = _np.sqrt(5) * d
            return (1 + t + t * t / 3) * _np.exp(-t)
        return _np.exp(-0.5 * d * d)  # Fallback to RBF


class RationalQuadratic(StationaryKernelMixin, NormalizedKernelMixin, Kernel):
    def __init__(self, length_scale=1.0, alpha=1.0,
                  length_scale_bounds=(1e-5, 1e5), alpha_bounds=(1e-5, 1e5)):
        self.length_scale = length_scale; self.alpha = alpha
    def __call__(self, X, Y=None, eval_gradient=False):
        from sklearn.metrics.pairwise import euclidean_distances
        Y = X if Y is None else Y
        d2 = euclidean_distances(X, Y, squared=True)
        return (1 + d2 / (2 * self.alpha * self.length_scale ** 2)) ** (-self.alpha)


class ExpSineSquared(StationaryKernelMixin, NormalizedKernelMixin, Kernel):
    def __init__(self, length_scale=1.0, periodicity=1.0,
                  length_scale_bounds=(1e-5, 1e5), periodicity_bounds=(1e-5, 1e5)):
        self.length_scale = length_scale; self.periodicity = periodicity
    def __call__(self, X, Y=None, eval_gradient=False):
        from sklearn.metrics.pairwise import euclidean_distances
        Y = X if Y is None else Y
        d = euclidean_distances(X, Y)
        return _np.exp(-2 * _np.sin(_np.pi * d / self.periodicity) ** 2
                       / self.length_scale ** 2)


class DotProduct(Kernel):
    def __init__(self, sigma_0=1.0, sigma_0_bounds=(1e-5, 1e5)):
        self.sigma_0 = sigma_0
    def __call__(self, X, Y=None, eval_gradient=False):
        Y = X if Y is None else Y
        return self.sigma_0 ** 2 + _np.asarray(X) @ _np.asarray(Y).T


class PairwiseKernel(Kernel):
    def __init__(self, gamma=1.0, gamma_bounds=(1e-5, 1e5), metric='linear',
                  pairwise_kernels_kwargs=None):
        self.gamma = gamma; self.metric = metric
        self.kwargs = pairwise_kernels_kwargs or {}
    def __call__(self, X, Y=None, eval_gradient=False):
        from sklearn.metrics.pairwise import pairwise_kernels
        return pairwise_kernels(X, Y, metric=self.metric,
                                  gamma=self.gamma, **self.kwargs)


class CompoundKernel(Kernel):
    def __init__(self, kernels):
        self.kernels = list(kernels)
    def __call__(self, X, Y=None, eval_gradient=False):
        return _np.stack([k(X, Y) for k in self.kernels], axis=-1)
